import React, { useState } from 'react';

const TestConnection = () => {
  const [status, setStatus] = useState('Not tested yet');
  const [loading, setLoading] = useState(false);

  const checkConnection = async () => {
    setLoading(true);
    setStatus('Testing connection...');
    try {
      // Connecting to the Spring Boot Backend Endpoint we created
      const response = await fetch('http://localhost:8081/api/test-db');

      if (!response.ok) {
        throw new Error(`HTTP Error! Status: ${response.status}`);
      }

      const data = await response.text();
      setStatus(`✅ Success: ${data}`);
    } catch (error) {
      console.error("Connection failed:", error);
      setStatus(`❌ Error: ${error.message} (Is the backend running on port 8081?)`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '20px', margin: '20px', border: '1px solid #ccc', borderRadius: '5px' }}>
      <h3>Database Connection Test</h3>
      <p>Test if the React frontend can talk to the Spring Boot backend, which then talks to Supabase.</p>

      <button 
        onClick={checkConnection} 
        disabled={loading}
        style={{ padding: '10px 15px', cursor: 'pointer', backgroundColor: '#007bff', color: 'white', border: 'none', borderRadius: '4px' }}
      >
        {loading ? 'Connecting...' : 'Test Connection'}
      </button>

      <div style={{ marginTop: '15px', padding: '10px', backgroundColor: '#f8f9fa', minHeight: '40px' }}>
        <strong>Status: </strong> {status}
      </div>
    </div>
  );
};

export default TestConnection;
